//! Read titles already generated by the agent; never start a model request.
use std::{
    fs::File,
    io::Read,
    path::{Path, PathBuf},
};

use serde_json::Value;

use crate::sessions::SessionManager;

const TITLE_READ_LIMIT: u64 = 32 * 1024 * 1024;

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct AgentSessionTitleSource {
    pub runtime_id: String,
    pub pane_id: String,
    pub adapter_id: String,
    pub session_id: String,
    pub transcript_path: Option<String>,
    pub cwd: Option<String>,
}

fn clean_title(value: &Value) -> Option<String> {
    let title = value
        .as_str()?
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    (!title.is_empty()).then(|| title.chars().take(256).collect())
}

pub(crate) fn title_from_jsonl(source: &AgentSessionTitleSource, content: &str) -> Option<String> {
    if source.adapter_id == "codex" {
        return codex_index_title(&source.session_id, content).flatten();
    }
    let mut generated = None;
    let mut custom = None;
    for line in content.lines() {
        let Ok(record) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        if source.adapter_id == "claude-code"
            && record["sessionId"].as_str() == Some(&source.session_id)
        {
            match record["type"].as_str() {
                Some("ai-title") => generated = clean_title(&record["aiTitle"]),
                Some("custom-title") => custom = clean_title(&record["customTitle"]),
                _ => {}
            }
        }
    }
    custom.or(generated)
}

// Outer None means absent; Some(None) means an explicitly cleared name.
fn codex_index_title(session_id: &str, content: &str) -> Option<Option<String>> {
    content
        .lines()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .filter(|record| record["id"].as_str() == Some(session_id))
        .map(|record| clean_title(&record["thread_name"]))
        .last()
}

fn codex_root(transcript: &str) -> Option<String> {
    let normalized = transcript.replace('\\', "/");
    for directory in ["/sessions/", "/archived_sessions/"] {
        if let Some((root, _)) = normalized.rsplit_once(directory) {
            return Some(root.to_string());
        }
    }
    None
}

fn title_path(source: &AgentSessionTitleSource, home: Option<&str>, local: bool) -> Option<String> {
    match source.adapter_id.as_str() {
        "codex" => {
            let root = source
                .transcript_path
                .as_deref()
                .and_then(codex_root)
                .or_else(|| local.then(|| std::env::var("CODEX_HOME").ok()).flatten())
                .or_else(|| home.map(|home| format!("{home}/.codex")))?;
            Some(format!("{root}/session_index.jsonl"))
        }
        "claude-code" => source.transcript_path.clone().or_else(|| {
            let home = home?;
            let cwd = source.cwd.as_deref()?;
            let project: String = cwd
                .chars()
                .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
                .collect();
            // Only construct a filename from an agent UUID, never from a path-like id.
            uuid::Uuid::parse_str(&source.session_id).ok()?;
            Some(format!(
                "{home}/.claude/projects/{project}/{}.jsonl",
                source.session_id
            ))
        }),
        _ => None,
    }
}

fn local_path(path: &str, target_id: &str) -> Option<PathBuf> {
    let Some(distribution) = target_id.strip_prefix("local:wsl:") else {
        return Some(PathBuf::from(path));
    };
    if !cfg!(windows) || !path.starts_with('/') {
        return None;
    }
    if let Some(mounted) = path.strip_prefix("/mnt/") {
        let (drive, rest) = mounted.split_once('/')?;
        if drive.len() == 1 && drive.as_bytes()[0].is_ascii_alphabetic() {
            return Some(PathBuf::from(format!("{drive}:/{}", rest)));
        }
    }
    if distribution.is_empty() || distribution.contains(['/', '\\']) {
        return None;
    }
    Some(PathBuf::from(format!(
        "\\\\wsl.localhost\\{distribution}{}",
        path.replace('/', "\\")
    )))
}

fn read_tail(path: &Path) -> Option<String> {
    let file = File::open(path).ok()?;
    let size = file.metadata().ok()?.len();
    if size > TITLE_READ_LIMIT {
        return None;
    }
    let mut bytes = Vec::new();
    file.take(TITLE_READ_LIMIT + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() as u64 > TITLE_READ_LIMIT {
        return None;
    }
    Some(String::from_utf8_lossy(&bytes).into_owned())
}

fn codex_state_title(root: &Path, session_id: &str) -> Option<String> {
    use rusqlite::{Connection, OpenFlags, OptionalExtension};
    // Read the live database rather than copying it: recent titles may be in WAL.
    // Missing databases/schemas remain a normal fallback, and are never created.
    let connection = Connection::open_with_flags(
        root.join("state_5.sqlite"),
        OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NO_MUTEX,
    )
    .ok()?;
    connection
        .busy_timeout(std::time::Duration::from_millis(100))
        .ok()?;
    let read = |query: &str| -> Option<String> {
        let value: Option<String> = connection
            .query_row(query, [session_id], |row| row.get(0))
            .optional()
            .ok()
            .flatten();
        clean_title(&Value::String(value?))
    };
    read("SELECT name FROM threads WHERE id = ?1")
        .or_else(|| read("SELECT title FROM threads WHERE id = ?1"))
}

fn local_title(source: &AgentSessionTitleSource, path: &Path) -> Option<String> {
    let content = read_tail(path);
    if source.adapter_id == "codex" {
        if let Some(indexed) = content
            .as_deref()
            .and_then(|content| codex_index_title(&source.session_id, content))
        {
            return indexed;
        }
        return codex_state_title(path.parent()?, &source.session_id);
    }
    title_from_jsonl(source, &content?)
}

pub(crate) async fn read_title(
    source: AgentSessionTitleSource,
    target_id: String,
    sessions: &SessionManager,
) -> Option<String> {
    if target_id.starts_with("ssh-bookmark:") {
        let home = if source.transcript_path.is_none() {
            sessions.remote_home(&source.runtime_id).await.ok()
        } else {
            None
        };
        let path = title_path(&source, home.as_deref(), false)?;
        use tokio::io::AsyncReadExt;
        let sftp = sessions.sftp(&source.runtime_id).await.ok()?;
        let metadata = sftp.symlink_metadata(path.clone()).await.ok()?;
        if !metadata.is_regular() || metadata.len() > TITLE_READ_LIMIT {
            return None;
        }
        let file = sftp.open(path).await.ok()?;
        let mut bytes = Vec::new();
        file.take(TITLE_READ_LIMIT + 1)
            .read_to_end(&mut bytes)
            .await
            .ok()?;
        if bytes.len() as u64 > TITLE_READ_LIMIT {
            return None;
        }
        return title_from_jsonl(&source, &String::from_utf8_lossy(&bytes));
    }
    let is_wsl = target_id.starts_with("local:wsl:");
    let home = if is_wsl {
        None
    } else {
        dirs::home_dir().map(|p| p.to_string_lossy().into_owned())
    };
    let path = local_path(&title_path(&source, home.as_deref(), !is_wsl)?, &target_id)?;
    tauri::async_runtime::spawn_blocking(move || local_title(&source, &path))
        .await
        .ok()
        .flatten()
}

#[cfg(test)]
mod tests {
    use super::*;
    fn source(adapter: &str) -> AgentSessionTitleSource {
        AgentSessionTitleSource {
            runtime_id: "runtime".into(),
            pane_id: "pane".into(),
            adapter_id: adapter.into(),
            session_id: "session".into(),
            transcript_path: None,
            cwd: None,
        }
    }
    #[test]
    fn codex_state_title_reads_live_wal_and_supports_older_schema_without_writing() {
        let root = std::env::temp_dir().join(format!("luna-state-title-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        assert!(codex_state_title(&root, "session").is_none());
        assert!(!root.join("state_5.sqlite").exists());
        let db = rusqlite::Connection::open(root.join("state_5.sqlite")).unwrap();
        db.execute_batch("PRAGMA journal_mode=WAL; PRAGMA wal_autocheckpoint=0; CREATE TABLE threads(id TEXT PRIMARY KEY, title TEXT); INSERT INTO threads VALUES('session', '修复终端颜色'), ('other', 'Wrong');").unwrap();
        assert_eq!(
            codex_state_title(&root, "session").as_deref(),
            Some("修复终端颜色")
        );
        assert!(codex_state_title(&root, "missing").is_none());
        db.execute_batch("ALTER TABLE threads ADD COLUMN name TEXT; UPDATE threads SET name='已有会话名称' WHERE id='session';").unwrap();
        assert_eq!(
            codex_state_title(&root, "session").as_deref(),
            Some("已有会话名称")
        );
        let index = root.join("session_index.jsonl");
        assert_eq!(
            local_title(&source("codex"), &index).as_deref(),
            Some("已有会话名称")
        );
        std::fs::write(
            &index,
            "{\"id\":\"session\",\"thread_name\":\"Index name\"}\n",
        )
        .unwrap();
        assert_eq!(
            local_title(&source("codex"), &index).as_deref(),
            Some("Index name")
        );
        std::fs::write(&index, "{\"id\":\"session\",\"thread_name\":\"Old\"}\n{\"id\":\"session\",\"thread_name\":\"\"}\n").unwrap();
        assert!(local_title(&source("codex"), &index).is_none());
        db.execute_batch("UPDATE threads SET name='', title='' WHERE id='session';")
            .unwrap();
        assert!(codex_state_title(&root, "session").is_none());
        drop(db);
        std::fs::remove_dir_all(root).unwrap();
    }
    #[test]
    fn codex_reads_latest_matching_name_and_skips_partial_records() {
        let input = "partial\n{\"id\":\"session\",\"thread_name\":\"Old\"}\n{\"id\":\"other\",\"thread_name\":\"Other\"}\n{\"id\":\"session\",\"thread_name\":\"修复 SSH 重连\"}\n{\"id\":";
        assert_eq!(
            title_from_jsonl(&source("codex"), input).as_deref(),
            Some("修复 SSH 重连")
        );
        assert_eq!(
            title_from_jsonl(
                &source("codex"),
                "{\"id\":\"session\",\"thread_name\":\"Old\"}\n{\"id\":\"session\",\"thread_name\":\"\"}"
            ),
            None
        );
    }
    #[test]
    fn claude_prefers_custom_title_and_ignores_other_sessions_and_messages() {
        let input = r#"{"type":"ai-title","sessionId":"session","aiTitle":"First"}
{"type":"custom-title","sessionId":"session","customTitle":"My name"}
{"type":"ai-title","sessionId":"session","aiTitle":"Later"}
{"type":"ai-title","sessionId":"other","aiTitle":"Wrong"}
{"type":"assistant","sessionId":"session","message":"Private message"}"#;
        assert_eq!(
            title_from_jsonl(&source("claude-code"), input).as_deref(),
            Some("My name")
        );
        assert_eq!(
            title_from_jsonl(
                &source("claude-code"),
                "{\"type\":\"ai-title\",\"sessionId\":\"session\",\"aiTitle\":\"  修复\\n重连  \"}"
            )
            .as_deref(),
            Some("修复 重连")
        );
    }
    #[test]
    fn paths_follow_transcript_location_including_custom_agent_homes() {
        let mut codex = source("codex");
        codex.transcript_path =
            Some("D:\\custom\\codex\\sessions\\2026\\10\\10\\rollout.jsonl".into());
        assert_eq!(
            title_path(&codex, None, false).as_deref(),
            Some("D:/custom/codex/session_index.jsonl")
        );
        codex.transcript_path = Some("/home/user/custom/archived_sessions/rollout.jsonl".into());
        assert_eq!(
            title_path(&codex, None, false).as_deref(),
            Some("/home/user/custom/session_index.jsonl")
        );
        let mut claude = source("claude-code");
        claude.transcript_path = Some("/custom/claude/projects/project/session.jsonl".into());
        assert_eq!(title_path(&claude, None, false), claude.transcript_path);
        assert_eq!(
            title_path(&source("unknown"), Some("/home/user"), false),
            None
        );
    }
    #[test]
    fn reads_middle_titles_and_falls_back_for_oversized_or_missing_files() {
        let path = std::env::temp_dir().join(format!("luna-title-{}.jsonl", uuid::Uuid::new_v4()));
        let mut bytes = b"{\"id\":\"session\",\"thread_name\":\"Old\"}\n".to_vec();
        bytes.extend(vec![b'x'; 2 * 1024 * 1024]);
        bytes.extend_from_slice(b"\n{\"id\":\"session\",\"thread_name\":\"Latest\"}\n");
        bytes.extend(vec![b'x'; 2 * 1024 * 1024]);
        std::fs::write(&path, bytes).unwrap();
        assert_eq!(
            title_from_jsonl(&source("codex"), &read_tail(&path).unwrap()).as_deref(),
            Some("Latest")
        );
        let file = std::fs::OpenOptions::new().write(true).open(&path).unwrap();
        file.set_len(TITLE_READ_LIMIT + 1).unwrap();
        assert!(read_tail(&path).is_none());
        drop(file);
        std::fs::remove_file(&path).unwrap();
        assert!(read_tail(&path).is_none());
    }
    #[cfg(windows)]
    #[test]
    fn wsl_paths_use_the_selected_distribution_or_mounted_drive() {
        assert_eq!(
            local_path("/home/user/index.jsonl", "local:wsl:Ubuntu"),
            Some(PathBuf::from(
                r"\\wsl.localhost\Ubuntu\home\user\index.jsonl"
            ))
        );
        assert_eq!(
            local_path("/mnt/d/custom/index.jsonl", "local:wsl:Ubuntu"),
            Some(PathBuf::from("d:/custom/index.jsonl"))
        );
        assert!(local_path("/home/user/index.jsonl", "local:wsl:../bad").is_none());
    }
}
